<h1 class="h">Dokumenty</h1><div class="sub">Centrální bezpečné úložiště příloh.</div><div class="card"><form class="row" method="post" action="/documents/files/upload" enctype="multipart/form-data"><input type="hidden" name="_csrf" value="<?=App\Core\Auth::csrf()?>"><input type="hidden" name="entity_type" value="general"><input type="file" name="file" required><button class="btn primary">Nahrát</button></form></div><div style="height:16px"></div><form class="actions"><input class="btn" name="q" value="<?=View::e($q)?>" placeholder="Hledat soubor…"><button class="btn">Hledat</button></form><div class="card tablewrap"><table class="table"><tr><th>Soubor</th><th>Typ</th><th>Velikost</th><th>Datum</th><th></th></tr><?php foreach($files as $f):?><tr><td><?=View::e($f['file_name'])?></td><td><?=View::e($f['mime_type'])?></td><td><?=number_format($f['size']/1024,1,',',' ')?> KB</td><td><?=View::e($f['created_at'])?></td><td><a class="btn" href="/documents/files/<?=$f['id']?>">Stáhnout</a></td></tr><?php endforeach;?></table></div>